node --input-type=module <<'JS'
import { DatabaseSync } from 'node:sqlite';
for (const db of ['/run/stage/state/palimpsest.sqlite','/run/stage/state/attempt_world_basis.sqlite','/run/stage/state/execution-associations.sqlite']) {
  console.log('=====', db);
  const d = new DatabaseSync(db, {readOnly:true});
  const tables = d.prepare("select name from sqlite_master where type='table' order by name").all();
  console.log(tables.map(t=>t.name).join(', '));
  for (const t of tables) {
    const cols = d.prepare(`pragma table_info(${JSON.stringify(t.name)})`).all();
    const names = cols.map(c=>c.name);
    if (names.some(n=>/attempt|world|path|repo/i.test(n))) {
      const rows = d.prepare(`select * from ${JSON.stringify(t.name)} limit 20`).all();
      console.log('--', t.name, names.join(','));
      for (const r of rows) console.log(JSON.stringify(r).slice(0,2000));
    }
  }
  d.close();
}
