node --input-type=module <<'JS'
import { DatabaseSync } from 'node:sqlite';
const d = new DatabaseSync('/run/stage/state/palimpsest.sqlite', {readOnly:true});
const rows = d.prepare("select * from attempts where project_id='psvr-c-energy'").all();
for (const r of rows) {
  console.log('--- attempt', r.attempt_id, r.state, r.updated_at);
  function decode(v){
    if (v && typeof v==='object' && !Buffer.isBuffer(v)) {
      const vals=Object.values(v); return Buffer.from(vals).toString('utf8');
    }
    if (v instanceof Uint8Array) return Buffer.from(v).toString('utf8');
    return typeof v==='string'?v:JSON.stringify(v);
  }
  console.log('report:', decode(r.report_json).slice(0,1000));
  console.log('state:', decode(r.state_json).slice(0,3000));
}
console.log('--- events');
const ev = d.prepare("select * from events where project_id='psvr-c-energy' order by rowid").all();
for (const e of ev) {
  const copy={...e};
  for (const k of ['payload_json','data_json','state_json']) if (copy[k] && typeof copy[k]==='object') copy[k]=Buffer.from(Object.values(copy[k])).toString('utf8');
  console.log(JSON.stringify(copy).slice(0,2000));
}
d.close();
