import { DatabaseSync } from 'node:sqlite';
function dec(v){
  if (v==null) return null;
  if (typeof v==='string') { try { return JSON.parse(v); } catch { return v; } }
  if (v instanceof Uint8Array) return JSON.parse(Buffer.from(v).toString('utf8'));
  if (typeof v==='object') {
    const vals=Object.values(v);
    if (vals.every(x=>typeof x==='number')) {
      const s=Buffer.from(vals).toString('utf8');
      try { return JSON.parse(s); } catch { return s; }
    }
  }
  return v;
}
const d = new DatabaseSync('/run/stage/state/attempt_world_basis.sqlite',{readOnly:true});
for (const r of d.prepare('select * from attempt_world_basis').all()) {
  console.log('===',r.attempt_id);
  console.log(JSON.stringify(dec(r.record_json),null,2).slice(0,8000));
}
d.close();
