import { DatabaseSync } from 'node:sqlite';
import { readdirSync } from 'node:fs';
const dir='/run/stage/state';
for (const f of readdirSync(dir)) {
  if (!f.endsWith('.sqlite')) continue;
  const p=dir+'/'+f;
  let d;
  try { d=new DatabaseSync(p,{readOnly:true}); } catch(e){ continue; }
  const tables=d.prepare("select name from sqlite_master where type='table'").all();
  for (const {name} of tables) {
    let rows;
    try { rows=d.prepare(`select * from ${JSON.stringify(name)}`).all(); } catch { continue; }
    for (const r of rows) {
      const s=JSON.stringify(r);
      if (/C:\/Users|C:\\\\Users|worlds\/|world_path|worldPath|worlds\\\\/.test(s)) {
        console.log('===',f,name);
        console.log(s.slice(0,5000));
      }
    }
  }
  d.close();
}
